/* Layers rows — fed exclusively by the live canvas DOM (buildLayerTree);
   mock tree removed in the E2.1 deslop pass (no fake values — Dan's law). */
type LayerIcon = 'frame' | 'image' | 'auto' | 'section' | 'toolbar' | 'component'
type Node = { name: string; icon: LayerIcon; depth: number; kids?: boolean; open?: boolean; locked?: boolean; visible?: boolean; sel?: boolean; comp?: boolean }
function LayerRow({ n, on, onToggle, rowId }: { n: Node; on?: () => void; onToggle?: () => void; rowId?: string }) {
  const [h, setH] = useState(false)
  const iconName: keyof typeof UI_ICON = n.icon === 'image' ? 'layerImage' : n.icon === 'auto' ? 'layerAuto' : n.icon === 'section' ? 'layerSection' : n.icon === 'toolbar' ? 'layerToolbar' : n.icon === 'component' ? 'layerComponent' : 'layerFrame'
  return (
    <div data-layer-row={rowId} onClick={on} onMouseEnter={() => setH(true)} onMouseLeave={() => setH(false)}
      style={{ display: 'grid', gridTemplateColumns: `${16 + n.depth * 24}px 16px minmax(0,1fr) 40px`, alignItems: 'center', height: 32, paddingRight: 8, background: n.sel ? '#dff3ff' : h ? '#f4f5f6' : 'transparent', cursor: 'pointer' }}>
      <span onClick={onToggle ? (e) => { e.stopPropagation(); onToggle() } : undefined} style={{ width: 16, height: 16, marginLeft: n.depth * 24, display: 'grid', placeItems: 'center', color: INK, cursor: onToggle ? 'pointer' : undefined }}>{n.kids && <UiIcon name={n.open ? 'caret16' : 'caretRight16'} size={16} />}</span>
      <span style={{ width: 16, height: 16, display: 'grid', placeItems: 'center', color: n.comp ? TOKEN : 'rgba(0,0,0,0.65)' }}><UiIcon name={iconName} size={16} /></span>
      <span style={{ minWidth: 0, paddingLeft: 8, font: `400 11px/16px ${FONT}`, color: n.comp ? TOKEN : INK, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{n.name}</span>
      <span style={{ display: 'flex', justifyContent: 'flex-end', alignItems: 'center', gap: 4, color: FAINT }}>
        {n.locked && <UiIcon name="layerLock" size={16} />}
        {n.visible && <UiIcon name="visibility" size={16} />}
      </span>
    </div>
  )
}

/* ── Variables library (full-page, opened by the Variables rail item) ──
   E3.4 traceability: every token shows its structural Name (the converter's own path, the
   DS/Figma-side name) ↔ CSS variable ↔ resolved value — so it's always clear what token is
   showing and how it maps to code. Real tokens from the converter output, no mock. */
/* #31 — parse a Figma variables JSON export into collections → variables → mode values. Handles the
   documented Figma shape ({ meta?: { variableCollections, variables } } or top-level), converting
   COLOR {r,g,b,a} (0–1) to hex. Returns null if it doesn't look like a Figma variables export. */
type ImportedVar = { name: string; type: string; values: string[]; scopes?: string[]; path?: string }
type ImportedCollection = { name: string; modes: string[]; vars: ImportedVar[] }
/* E6.7 — Dan's REAL export (SSOT: storybook/design-system/variables/figma-export.json) is the
   variables2json shape: an ARRAY of `{ "<coll>": { modes: { "<Mode>": { <group…>: { <leaf>:
   {$type,$value,$scopes} } } } } }` with HEX originals. Parse it first; REST + plugin shapes stay. */
function parseVariables2Json(data: unknown): ImportedCollection[] | null {
  if (!Array.isArray(data) || !data.length || typeof data[0] !== 'object') return null
  const out: ImportedCollection[] = []
  for (const item of data as Record<string, { modes?: Record<string, unknown> }>[]) {
    const coll = Object.keys(item)[0]
    if (!coll || !item[coll]?.modes) return null // not this shape
    const modes = Object.keys(item[coll].modes!)
    const byPath = new Map<string, ImportedVar>()
    modes.forEach((mode, mi) => {
      const walk = (node: unknown, path: string[]) => {
        if (!node || typeof node !== 'object') return
        const rec = node as Record<string, unknown> & { $value?: unknown; $type?: string; $scopes?: string[] }
        if ('$value' in rec) {
          const key = path.join(' / ')
          const v = byPath.get(key) ?? { name: key, type: rec.$type ?? '', values: Array(modes.length).fill(''), scopes: rec.$scopes, path: key }
          v.values[mi] = String(rec.$value)
          byPath.set(key, v)
          return
        }
        for (const [k, val] of Object.entries(rec)) if (!k.startsWith('$')) walk(val, path.concat(k))
      }
      walk(item[coll].modes![mode], [])
    })
    out.push({ name: coll, modes, vars: [...byPath.values()] })
  }
  return out
}
function parseFigmaVariables(data: unknown): ImportedCollection[] | null {
  const v2j = parseVariables2Json(data)
  if (v2j) return v2j
  const meta = ((data as { meta?: unknown }).meta ?? data) as { variableCollections?: unknown; variables?: unknown; collections?: unknown }
  // Accept both documented shapes: REST export (variableCollections/variables as id-keyed OBJECTS)
  // and plugin export ({ collections: [...], variables: [...] } as ARRAYS) — Codex E5 MED finding.
  const toRecord = (v: unknown): Record<string, unknown> | null =>
    Array.isArray(v) ? Object.fromEntries((v as { id?: string }[]).map((x, i) => [x?.id ?? String(i), x]))
    : v && typeof v === 'object' ? v as Record<string, unknown> : null
  const cols = toRecord(meta.variableCollections ?? meta.collections)
  const vars = toRecord(meta.variables)
  if (!cols || !vars) return null
  const chan = (c: number) => Math.round(Math.max(0, Math.min(1, c)) * 255).toString(16).padStart(2, '0')
  const fmt = (v: unknown): string => {
    if (v && typeof v === 'object' && 'r' in (v as object)) { const c = v as { r: number; g: number; b: number; a?: number }; return `#${chan(c.r)}${chan(c.g)}${chan(c.b)}${c.a !== undefined && c.a < 1 ? chan(c.a) : ''}`.toUpperCase() }
    if (v && typeof v === 'object' && 'id' in (v as object)) return `→ ${(v as { id: string }).id}` // variable alias
    return String(v ?? '')
  }
  return Object.values(cols as Record<string, { name?: string; modes?: { modeId: string; name: string }[]; variableIds?: string[] }>).map((c) => {
    const modes = (c.modes ?? []).map((m) => m.name), modeIds = (c.modes ?? []).map((m) => m.modeId)
    const vlist = (c.variableIds ?? []).map((id) => (vars as Record<string, { name?: string; resolvedType?: string; type?: string; valuesByMode?: Record<string, unknown> }>)[id]).filter(Boolean).map((v) => ({
      name: v.name ?? '', type: v.resolvedType ?? v.type ?? '', values: modeIds.map((mid) => fmt(v.valuesByMode?.[mid])),
    }))
    return { name: c.name ?? 'Collection', modes, vars: vlist }
  })
}
function VariablesLibrary() {
  const tokens = useDsTokens()
  const [colSel, setColSel] = useState(0)
  const [q, setQ] = useState('')
  const [imported, setImported] = useState<{ file: string; collections: ImportedCollection[] } | null>(null)
  const [importErr, setImportErr] = useState<string | null>(null)
  // E6.7 — the Figma JSON is the SSOT: auto-load the repo export on open so the library shows the
  // figma side (structure + HEX originals) by default; Load-JSON can still swap in another file.
  useEffect(() => {
    fetch('/api/dev/editor-tokens?figma=1').then((r) => (r.ok ? r.json() : null)).then((d: { file: string; data: unknown } | null) => {
      if (!d) return
      const parsed = parseFigmaVariables(d.data)
      if (parsed) setImported((cur) => cur ?? { file: d.file.split('/').pop() ?? d.file, collections: parsed })
    }).catch(() => {})
  }, [])
  // Code-equivalents join: converter path ("primCol / base / white") ← collection camel + var path.
  const collCamelClient = (n: string) => n.replace(/^[\d.]+-/, '').split(/[-_\s]+/).filter(Boolean)
    .map((w, i) => (i === 0 ? w.toLowerCase() : w[0].toUpperCase() + w.slice(1).toLowerCase())).join('')
  const byPath = useMemo(() => { const m = new Map<string, DsToken>(); for (const t of tokens) if (t.path) m.set(t.path, t); return m }, [tokens])
  const loadJson = (file: File) => {
    file.text().then((txt) => {
      try { const parsed = parseFigmaVariables(JSON.parse(txt)); if (!parsed) { setImportErr('Not a Figma variables export (need variableCollections + variables).'); return } setImported({ file: file.name, collections: parsed }); setImportErr(null) }
      catch { setImportErr('Invalid JSON file.') }
    })
  }
  // #32: resizable Name / CSS-variable columns (Light/Dark absorb the remainder). Handle is an
  // absolute overlay at the cell's right edge so it consumes no layout width — header and rows stay
  // aligned by the shared width value alone.
  const [colW, setColW] = useState({ name: 220, css: 220 })
  const dragCol = (key: 'name' | 'css') => (e: React.PointerEvent) => {
    e.preventDefault()
    const startX = e.clientX, startW = colW[key]
    const onMove = (ev: PointerEvent) => setColW((w) => ({ ...w, [key]: Math.max(120, Math.min(480, startW + (ev.clientX - startX))) }))
    const onUp = () => { window.removeEventListener('pointermove', onMove); window.removeEventListener('pointerup', onUp) }
    window.addEventListener('pointermove', onMove); window.addEventListener('pointerup', onUp)
  }
  const colHandle = (key: 'name' | 'css') => (
    <span role="separator" aria-label={`Resize ${key} column`} onPointerDown={dragCol(key)}
      onDoubleClick={() => setColW((w) => ({ ...w, [key]: 220 }))} // dbl-click = auto-fit/reset (Dan); flex columns re-distribute
      style={{ position: 'absolute', right: 0, top: 0, bottom: 0, width: 9, cursor: 'col-resize', zIndex: 1 }} />
  )
  const collOf = (t: DsToken) => t.path?.split(' / ')[0] ?? t.group
  const collections: [string, number][] = []
  for (const t of tokens) {
    const c = collOf(t)
    const hit = collections.find((x) => x[0] === c)
    if (hit) hit[1]++
    else collections.push([c, 1])
  }
  const activeCol = collections[colSel]?.[0] ?? ''
  const ql = q.trim().toLowerCase()
  const rows = tokens.filter((t) => collOf(t) === activeCol)
    .filter((t) => !ql || (t.path ?? '').toLowerCase().includes(ql) || t.cssVar.toLowerCase().includes(ql) || t.value.toLowerCase().includes(ql))
  const activeImported = imported?.collections[colSel] ?? null
  const importedRows = activeImported ? activeImported.vars.filter((v) => !ql || v.name.toLowerCase().includes(ql) || v.values.some((x) => x.toLowerCase().includes(ql))) : []
  const isColorVal = (s: string) => /^#[0-9a-f]{6,8}$/i.test(s)
  return (
    <div style={{ flex: 1, minWidth: 0, display: 'flex', overflow: 'hidden' }}>
      {/* collections */}
      <div style={{ width: 260, flex: 'none', borderRight: `1px solid ${LINE}`, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
        <div style={{ height: 40, borderBottom: `1px solid ${LINE}`, display: 'flex', alignItems: 'center', gap: 6, padding: '0 12px' }}>
          <span style={{ flex: 1, minWidth: 0, font: `550 12px/1 ${FONT}`, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }} title={imported ? imported.file : undefined}>{imported ? `Figma · ${imported.file}` : `ONEMO DS · ${tokens.length} tokens`}</span>
          {imported && <button type="button" title="Back to DS tokens" onClick={() => { setImported(null); setColSel(0) }} style={{ appearance: 'none', border: 0, background: 'transparent', cursor: 'pointer', color: MUTE, font: `400 15px/1 ${FONT}`, padding: 0 }}>×</button>}
          <IB I={Sidebar} title="Toggle panel" s={15} />
        </div>
        {/* #31: import a Figma variables JSON export and render it in figma format */}
        <label title="Load a Figma variables JSON export" style={{ margin: '8px 12px 2px', height: 26, borderRadius: 6, border: `1px solid ${LINE}`, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 6, cursor: 'pointer', font: `450 11px/1 ${FONT}`, color: INK }}>
          <input type="file" accept="application/json,.json" style={{ display: 'none' }} onChange={(e) => { const f = e.currentTarget.files?.[0]; if (f) loadJson(f); e.currentTarget.value = '' }} />
          ↥ Load Figma JSON
        </label>
        {importErr && <div style={{ padding: '2px 12px 4px', font: `400 10px/1.4 ${FONT}`, color: '#d33' }}>{importErr}</div>}
        <div style={{ padding: '8px 12px 4px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}><span style={hdr}>Collections</span></div>
        <div style={{ flex: 1, overflowY: 'auto', padding: '0 6px' }}>
          {(imported ? imported.collections.map((c, i) => [c.name, c.vars.length, i] as [string, number, number]) : collections.map(([n, c], i) => [n, c, i] as [string, number, number])).map(([n, c, i]) => (
            <button key={`${n}-${i}`} type="button" onClick={() => setColSel(i)} style={{ appearance: 'none', border: 0, cursor: 'pointer', width: '100%', height: 30, display: 'flex', alignItems: 'center', gap: 8, padding: '0 8px', borderRadius: 5, background: i === colSel ? '#f0f1f3' : 'transparent', color: INK }}>
              <span style={{ flex: 1, minWidth: 0, textAlign: 'left', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', font: `${i === colSel ? 550 : 400} 11px/1 ${FONT}` }}>{n}</span>
              <span style={{ flex: 'none', color: MUTE, font: `400 11px/1 ${FONT}` }}>{c}</span>
            </button>
          ))}
        </div>
      </div>
      {/* traceability table: Name · CSS variable · Light · Dark — grouped like Figma's variables editor */}
      <div style={{ flex: 1, minWidth: 0, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
        <div style={{ height: 40, borderBottom: `1px solid ${LINE}`, display: 'flex', alignItems: 'center', gap: 12, padding: '0 16px' }}>
          <span style={{ font: `550 12px/1 ${FONT}` }}>{imported ? (activeImported?.name ?? '—') : activeCol}</span>
          <span style={{ color: MUTE, font: `400 11px/1 ${FONT}` }}>{imported ? importedRows.length : rows.length}</span>
          <div style={{ marginLeft: 'auto', display: 'flex', alignItems: 'center', gap: 8 }}>
            <div style={{ width: 200, height: 26, background: FIELD, borderRadius: 6, display: 'flex', alignItems: 'center', gap: 6, padding: '0 8px', color: MUTE, font: `400 11px/1 ${FONT}` }}>
              <MagnifyingGlass size={13} />
              <input value={q} onChange={(e) => setQ(e.currentTarget.value)} placeholder="Search name / var / value" style={{ flex: 1, minWidth: 0, border: 0, outline: 0, background: 'transparent', color: INK, font: `400 11px/1 ${FONT}` }} />
            </div>
          </div>
        </div>
        <div style={{ height: 32, borderBottom: `1px solid ${LINE}`, display: 'flex', alignItems: 'center', font: `550 11px/1 ${FONT}`, color: MUTE }}>
          {imported
            ? (<>
                <span style={{ width: colW.name, padding: '0 16px', position: 'relative' }}>Variable{colHandle('name')}</span>
                {(activeImported?.modes ?? []).map((m) => <span key={m} style={{ flex: 1, padding: '0 12px', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{m} <span style={{ color: FAINT }}>(figma)</span></span>)}
                <span style={{ width: colW.css, padding: '0 12px', position: 'relative', borderLeft: `1px solid ${LINE}` }}>CSS variable{colHandle('css')}</span>
                <span style={{ flex: 1, padding: '0 12px' }}>Code value</span>
              </>)
            : (<><span style={{ width: colW.name, padding: '0 16px', position: 'relative' }}>Name{colHandle('name')}</span><span style={{ width: colW.css, padding: '0 12px', position: 'relative' }}>CSS variable{colHandle('css')}</span><span style={{ flex: 1, padding: '0 12px' }}>Light</span><span style={{ flex: 1, padding: '0 12px' }}>Dark</span></>)}
        </div>
        <div style={{ flex: 1, overflowY: 'auto' }}>
          {imported ? (
            importedRows.length === 0
              ? <div style={{ padding: '16px', color: MUTE, font: `400 11px/1 ${FONT}` }}>No variables match.</div>
              : importedRows.map((v, i) => {
                  const code = activeImported && v.path ? byPath.get(`${collCamelClient(activeImported.name)} / ${v.path}`) : undefined
                  return (
                    <div key={`${v.name}-${i}`} title={v.scopes?.join(', ')} style={{ minHeight: 34, borderBottom: '1px solid #f2f2f3', display: 'flex', alignItems: 'center', font: `400 11px/1 ${FONT}` }}>
                      <span style={{ width: colW.name, padding: '0 16px', minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', color: INK }}>{v.name}</span>
                      {v.values.map((val, k) => (
                        <span key={k} style={{ flex: 1, padding: '0 12px', display: 'flex', alignItems: 'center', gap: 8, minWidth: 0 }}>
                          {isColorVal(val) && <span style={{ flex: 'none', width: 14, height: 14, borderRadius: 3, background: val, boxShadow: 'inset 0 0 0 1px rgba(0,0,0,.12)' }} />}
                          <span style={{ minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{val}</span>
                        </span>
                      ))}
                      <span style={{ width: colW.css, padding: '0 12px', minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', color: MUTE, borderLeft: `1px solid ${LINE}`, alignSelf: 'stretch', display: 'flex', alignItems: 'center' }}>{code?.cssVar ?? '—'}</span>
                      <span style={{ flex: 1, padding: '0 12px', display: 'flex', alignItems: 'center', gap: 8, minWidth: 0 }}>
                        {code && code.kind === 'color' && <span style={{ flex: 'none', width: 14, height: 14, borderRadius: 3, background: code.value, boxShadow: 'inset 0 0 0 1px rgba(0,0,0,.12)' }} />}
                        <span style={{ minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{code?.value ?? ''}</span>
                      </span>
                    </div>
                  )
                })
          ) : (() => {
            const valCell = (val: string, isColor: boolean) => (
              <span style={{ flex: 1, padding: '0 12px', display: 'flex', alignItems: 'center', gap: 8, minWidth: 0 }}>
                {isColor && <span style={{ flex: 'none', width: 14, height: 14, borderRadius: 3, background: val, boxShadow: 'inset 0 0 0 1px rgba(0,0,0,.12)' }} />}
                <span style={{ minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{val}</span>
              </span>
            )
            const out: React.ReactNode[] = []
            let lastGroup: string | null = null
            for (const t of rows) {
              const parts = (t.path ?? t.cssVar).split(' / ')
              const grp = parts.length > 2 ? parts[1] : ''
              if (grp !== lastGroup) {
                lastGroup = grp
                if (grp) out.push(<div key={`h-${grp}`} style={{ padding: '12px 16px 6px', font: `600 11px/1 ${FONT}`, color: INK }}>{grp}</div>)
              }
              const name = (parts.length > 2 ? parts.slice(2) : parts.slice(1)).join(' / ')
              const isColor = t.kind === 'color'
              out.push(
                <div key={t.cssVar} style={{ minHeight: 34, borderBottom: '1px solid #f2f2f3', display: 'flex', alignItems: 'center', font: `400 11px/1 ${FONT}` }}>
                  <span style={{ width: colW.name, padding: '0 16px', display: 'flex', alignItems: 'center', gap: 10, minWidth: 0 }}>
                    {isColor ? <span style={{ flex: 'none', width: 14, height: 14, borderRadius: 3, background: t.value, boxShadow: 'inset 0 0 0 1px rgba(0,0,0,.12)' }} /> : <VariableHashIcon />}
                    <span style={{ minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{name}</span>
                  </span>
                  <span style={{ width: colW.css, padding: '0 12px', minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', color: MUTE }}>{t.cssVar}</span>
                  {valCell(t.value, isColor)}
                  {valCell(t.dark ?? t.value, isColor)}
                </div>,
              )
            }
            return out
          })()}
          {rows.length === 0 && <div style={{ padding: '16px', color: MUTE, font: `400 11px/1 ${FONT}` }}>No tokens match.</div>}
        </div>
      </div>
    </div>
  )
}

/* E3.6 — Advanced stroke settings: border-style (Solid/Dashed/Dotted) — the CSS-analog subset. */
function StrokeSettingsMenu({ onStyle }: { onStyle: (value: string) => void }) {
  const [open, setOpen] = useState(false)
  const ref = useCloseOnOutside<HTMLDivElement>(open, () => setOpen(false))
  return (
    <div ref={ref} style={{ position: 'relative' }}>
      <UiIB name="autoLayoutSettings" title="Advanced stroke settings" active={open} on={() => setOpen((v) => !v)} />
      {open && (
        <div data-figma-floating-root="true" role="menu" style={{ position: 'absolute', right: 0, top: 28, zIndex: 130, width: 180, padding: '6px 12px', borderRadius: 8, background: '#fff', boxShadow: 'rgba(0,0,0,0.15) 0px 2px 5px 0px, rgba(0,0,0,0.12) 0px 10px 16px 0px, rgba(0,0,0,0.12) 0px 0px 0.5px 0px' }}>
          <div style={{ font: `500 9px/14px ${FONT}`, letterSpacing: '0.27px', color: 'rgba(0,0,0,0.5)', marginBottom: 4 }}>Style</div>
          <div style={{ display: 'flex', gap: 4 }}>
            {(['solid', 'dashed', 'dotted'] as const).map((s) => (
              <button key={s} type="button" onClick={() => onStyle(s)}
                style={{ appearance: 'none', border: `1px solid ${LINE}`, background: '#fff', height: 24, padding: '0 8px', borderRadius: 5, cursor: 'pointer', font: `400 11px/1 ${FONT}`, color: INK, textTransform: 'capitalize' }}>{s}</button>
            ))}
          </div>
        </div>
      )}
    </div>
  )
}

/* E4-G3 — Code mode: floating source view of the selected element (reads /api/dev/editor-source). */
function CodeView({ file, line, onClose }: { file: string; line: number; onClose: () => void }) {
  const [data, setData] = useState<{ from: number; snippet: string[] } | null>(null)
  useEffect(() => {
    setData(null)
    fetch(`/api/dev/editor-source?file=${encodeURIComponent(file)}&line=${line}`)
      .then((r) => (r.ok ? r.json() : null)).then((d) => d && setData(d)).catch(() => {})
  }, [file, line])
  return createPortal(
    <div data-figma-floating-root="true" style={{ position: 'fixed', right: 320, bottom: 24, width: 460, maxHeight: 340, zIndex: 1500, borderRadius: 10, background: '#1e1e1e', color: '#e6e6e6', boxShadow: '0 8px 28px rgba(0,0,0,0.35)', overflow: 'hidden', font: '400 11px/1.6 ui-monospace, "SF Mono", Menlo, monospace' }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '8px 12px', borderBottom: '1px solid #333', font: `500 11px/1 ${FONT}` }}>
        <span style={{ flex: 1, minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', color: '#bbb' }}>{file}:{line}</span>
        <button type="button" aria-label="Close code view" onClick={onClose} style={{ appearance: 'none', border: 0, background: 'transparent', color: '#bbb', cursor: 'pointer', fontSize: 16, lineHeight: 1 }}>×</button>
      </div>
      <div style={{ overflow: 'auto', maxHeight: 296, padding: '8px 0' }}>
        {data ? data.snippet.map((t, i) => { const n = data.from + i; const cur = n === line; return (
          <div key={n} style={{ display: 'flex', background: cur ? 'rgba(80,140,255,0.16)' : 'transparent', padding: '0 12px' }}>
            <span style={{ width: 38, flex: 'none', color: '#666', textAlign: 'right', paddingRight: 12, userSelect: 'none' }}>{n}</span>
            <span style={{ whiteSpace: 'pre', color: cur ? '#fff' : '#d4d4d4' }}>{t || ' '}</span>
          </div>
        ) }) : <div style={{ padding: '12px', color: '#888' }}>Loading source…</div>}
      </div>
    </div>,
    document.body,
  )
}

/* E4-G5 — Distribute menu (Position "more"): distribute the element's children along the main axis
   → justify-content space-between/around/evenly (real analog when the element is a flex container). */
